definition.raw:
The quiver Hecke algebra $H_{n}(\Gamma)$ associated to $\Gamma$ is a (possibly non-unitary) $k$-algebra with generators $\{1_{\alpha}\}_{\alpha\in K^{n}}$, $\{x_{a}\}_{1\leq a\leq n}$ and $\{\tau_{i}\}_{1\leq i\leq n-1}$ and relations:

\begin{align}
1_{\alpha}1_{\alpha'}&=\delta_{\alpha,\alpha'}1_{\alpha},\qquad\sum_{\alpha\in K^{n}}1_{\alpha}=1;\label{rel-def-QHA1}\\[0.2em]
\tau_{i}1_{\alpha}&=1_{s_{i}(\alpha)}\tau_{i},\qquad x_{a}1_{\alpha}=1_{\alpha}x_{a};\label{rel-def-QHA2}\\[0.2em]
x_{a}x_{b}&=x_{b}x_{a},\qquad \quad \tau_{i}\tau_{j}=\tau_{j}\tau_{i} \quad \mbox{if $\vert i-j\vert \geq 2$;}\label{rel-def-QHA3}\\[0.2em]
\tau_{i}x_{a}1_{\alpha}-x_{s_{i}(a)}\tau_{i}1_{\alpha}&=\left\{
\begin{array}{ll}
-1_{\alpha}&\text{if $a=i$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
1_{\alpha}&\text{if $a=i+1$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
0&\text{otherwise;}
\end{array}
\right.\label{rel-def-QHA4}\\[0.2em]
\tau_{i}^{2}1_{\alpha}&=Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1})1_{\alpha};\label{rel-def-QHA5}\\[0.2em]
\nonumber\tau_{i+1}\tau_{i}\tau_{i+1}1_{\alpha}-\tau_{i}\tau_{i+1}\tau_{i}1_{\alpha}&=\end{align}
\begin{align}
\left\{
\begin{array}{ll}
(x_{i+2}-x_{i})^{-1}(Q_{\alpha_i, \alpha_{i+1}}(x_{i+2}, x_{i+1})-Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1}))1_{\alpha}&\text{if $\alpha_i = \alpha_{i+2}$},\\[0.3em]
0&\text{otherwise,}
\end{array}
\right.\label{rel-def-QHA6}
\end{align}
for $\alpha,\alpha'\in K^{n},$ $1\leq a,b\leq n$ and $1\leq i,j\leq n-1,$ and where\\
\[Q_{\alpha_i, \alpha_{i+1}}(u, v)=\left\{
\begin{array}{ll}
0&\text{if $\alpha_i = \alpha_{i+1}$},\\[0.05em]
1&\text{if $\alpha_i\nslash \alpha_{i+1}$},\\[0.05em]
v-u&\text{if $\alpha_i\rightarrow \alpha_{i+1}$},\\[0.05em]
u-v&\text{if $\alpha_i\leftarrow \alpha_{i+1}$},\\[0.05em]
-(u-v)^{2}&\text{if $\alpha_i\rightleftarrows \alpha_{i+1}$}.
\end{array}
\right.\]

The affine Yokonuma-Hecke algebra, denoted by $\widehat{Y}_{r,n}(q)$, is an $\mathcal{R}$-associative algebra generated by the elements $t_{1},\ldots,t_{n},g_{1},\ldots,g_{n-1},X_{1}^{\pm1},$ in which the generators $t_{1},\ldots,t_{n},g_{1},$ $\ldots,g_{n-1}$ satisfy the following relations:
\begin{align}
g_ig_j&=g_jg_i \qquad \qquad\qquad\quad\hspace{0.3cm}\mbox{for all $i,j=1,\ldots,n-1$ such that $\vert i-j\vert \geq 2$;}\label{rel-def-Y1}\\[0.1em]
g_ig_{i+1}g_i&=g_{i+1}g_ig_{i+1} \qquad \quad\qquad\hspace{0.05cm}\mbox{for all $i=1,\ldots,n-2$;}\label{rel-def-Y2}\\[0.1em]
t_it_j&=t_jt_i \qquad\qquad\qquad\qquad  \mbox{for all $i,j=1,\ldots,n$;}\label{rel-def-Y3}\\[0.1em]
g_it_j&=t_{s_i(j)}g_i \quad \quad\qquad\qquad\hspace{0.25cm}\mbox{for all $i=1,\ldots,n-1$ and $j=1,\ldots,n$;}\label{rel-def-Y4}\\[0.1em]
t_i^r&=1 \quad \qquad\qquad\qquad\qquad\mbox{for all $i=1,\ldots,n$;}\label{rel-def-Y5}\\[0.2em]
g_{i}^{2}&=q+(q-1)e_{i}g_{i} \qquad \hspace{0.48cm}\mbox{for all $i=1,\ldots,n-1$;}\label{rel-def-Y6}
\end{align}
where $s_{i}$ is the transposition $(i,i+1)$, and for each $1\leq i\leq n-1$,
$$e_{i} :=\frac{1}{r}\sum\limits_{s=0}^{r-1}t_{i}^{s}t_{i+1}^{-s},$$
together with the following relations concerning the generators $X_{1}^{\pm1}$:
\begin{align}
X_{1}X_{1}^{-1}&=X_{1}^{-1}X_{1}=1;\label{rel-def-Y7}\\[0.1em]
g_{1}X_{1}g_{1}X_{1}&=X_{1}g_{1}X_{1}g_{1};\label{rel-def-Y8}\\[0.1em]
g_{i}X_{1}&=X_{1}g_{i} \qquad \qquad \quad\mbox{for all $i=2,\ldots,n-1$;}\label{rel-def-Y9}\\[0.1em]
t_{j}X_{1}&=X_{1}t_{j} \qquad \qquad\quad\mbox{for all $j=1,\ldots,n$;}\label{rel-def-Y10}
\end{align}

We define inductively elements $X_{2},\ldots,X_{n}$ in $\widehat{Y}_{r,n}(q)$ by
\begin{equation}
X_{i+1} :=q^{-1}g_{i}X_{i}g_{i}\quad\mathrm{for}~i=1,\ldots,n-1.

The degenerate affine Yokonuma-Hecke algebra, denoted by $\widehat{Y}_{r,n}(1)$, is an $\mathcal{R}$-associative algebra generated by the elements $t_{1},\ldots,t_{n},f_{1},\ldots,f_{n-1},y_1,\ldots, y_{n}$ in which the generators $t_{1},\ldots,t_{n},g_{1},$ $\ldots,g_{n-1}$ satisfy the following relations:
\begin{align}
f_if_j&=f_jf_i \qquad \qquad\qquad\quad\hspace{0.3cm}\mbox{for all $i,j=1,\ldots,n-1$ such that $\vert i-j\vert \geq 2$;}\label{drel-def-Y1}\\[0.1em]
f_if_{i+1}f_i&=f_{i+1}f_if_{i+1} \qquad \quad\qquad\hspace{0.05cm}\mbox{for all $i=1,\ldots,n-2$;}\label{drel-def-Y2}\\[0.1em]
t_it_j&=t_jt_i \qquad\qquad\qquad\qquad  \mbox{for all $i,j=1,\ldots,n$;}\label{drel-def-Y3}\\[0.1em]
f_it_j&=t_{s_i(j)}f_i \quad \quad\qquad\qquad\hspace{0.25cm}\mbox{for all $i=1,\ldots,n-1$ and $j=1,\ldots,n$;}\label{drel-def-Y4}\\[0.1em]
t_i^r&=1 \quad \qquad\qquad\qquad\qquad\mbox{for all $i=1,\ldots,n$;}\label{drel-def-Y5}\\[0.2em]
f_{i}^{2}&=1 \qquad \hspace{2.71cm}\mbox{for all $i=1,\ldots,n-1$;}\label{drel-def-Y6}
\end{align}
together with the following relations concerning the generators $y_1,\ldots, y_{n}$:
\begin{align}
y_{i}y_{j}&=y_{j}y_{i};\label{drel-def-Y7}\\[0.1em]
f_{i}y_{i+1}&=y_{i}f_{i}+e_{i};\label{drel-def-Y8}\\[0.1em]
f_{i}y_{j}&=y_{j}f_{i} \qquad \qquad \quad\mbox{for all $j\neq i, i+1$;}\label{drel-def-Y9}\\[0.1em]
t_{j}y_{i}&=y_{i}t_{j} \hspace{0.07cm}\qquad \qquad\quad\mbox{for all $i, j=1,\ldots,n$;}\label{drel-def-Y10}
\end{align}
where for each $1\leq i\leq n-1$,
$$e_{i} :=\frac{1}{r}\sum\limits_{s=0}^{r-1}t_{i}^{s}t_{i+1}^{-s}.$$

