Quiver Hecke algebras
Let $r, n\in \mathbb{Z}_{\geq 1},$ and let $k$ be a field which contains a primitive $r$th root of unity $\zeta.$ Let $p$ be the characteristic of $k$ and consider an element $q\in k^{*}.$ We denote by $e$ the smallest integer such that $1+q+\cdots+q^{e-1}=0$, and set $e:=\infty$ if no such integer exists.

Assume first that $q=1.$ Given a subset $I$ of $k,$ we denote by $I_{1}$ the quiver with set of vertices $I$ and with an arrow $i\rightarrow i+1$ whenever $i, i+1\in I.$

Assume now that $q\neq 1.$ Given a subset $I$ of $k^{*},$ we denote by $I_{q}$ the quiver with set of vertices $I$ and with an arrow $i\rightarrow qi$ whenever $i, qi\in I.$

Assume that $I_{q}$ is connected. Note that when $q=1,$ $I_{q}$ has type $A_{\ell}$ if $\vert I\vert=\ell< p$ or $|I|=\ell$ and $p=0;$ type $A_{\infty}$ if $|I|=\infty$ and $p=0;$ type $\widetilde{A}_{p-1}$ if $|I|=p> 0.$ When $q\neq 1,$ $I_{q}$ has type $A_{\ell}$ if $\vert I\vert=\ell< e$ or $|I|=\ell$ and $e=\infty;$ type $A_{\infty}$ if $|I|=\infty$ and $e=\infty;$ type $\widetilde{A}_{e-1}$ if $|I|=e> 0.$

Let $J=\{0,1,\ldots,r-1\}$. We now define the quiver $\Gamma=\coprod_{j\in J} I_{q},$ which is $r$ disjoint copies of $I_{q}.$ Hence, the vertices of $\Gamma$ are the elements of $K=I\times J$ and there is an arrow between $(i, j)$ and $(i', j')$ in $\Gamma$ if and only if there is an arrow between $i$ and $i'$ in $I_{q}$ and $j=j'.$ For $k, k'\in K,$ we write $k\rightleftarrows k'$ whenever $k\rightarrow k'$ and $k'\rightarrow k$; this happens only when $e=2.$ Finally, we write $k\nslash k'$ if $k\neq k'$ and if there is no arrow between these two vertices. The action of $\mathfrak{S}_{n}$ on $K^{n}=I^{n}\times J^{n}$ is given by the diagonal action, that is, $\sigma\cdot(\nu, j)=(\sigma(\nu), \sigma(j))$ for any $(\nu, j)\in K^{n}$ and $\sigma\in \mathfrak{S}_{n}.$

\begin{definition}
The quiver Hecke algebra $H_{n}(\Gamma)$ associated to $\Gamma$ is a (possibly non-unitary) $k$-algebra with generators $\{1_{\alpha}\}_{\alpha\in K^{n}}$, $\{x_{a}\}_{1\leq a\leq n}$ and $\{\tau_{i}\}_{1\leq i\leq n-1}$ and relations:

\begin{align}
1_{\alpha}1_{\alpha'}&=\delta_{\alpha,\alpha'}1_{\alpha},\qquad\sum_{\alpha\in K^{n}}1_{\alpha}=1;\label{rel-def-QHA1}\\[0.2em]
\tau_{i}1_{\alpha}&=1_{s_{i}(\alpha)}\tau_{i},\qquad x_{a}1_{\alpha}=1_{\alpha}x_{a};\label{rel-def-QHA2}\\[0.2em]
x_{a}x_{b}&=x_{b}x_{a},\qquad \quad \tau_{i}\tau_{j}=\tau_{j}\tau_{i} \quad \mbox{if $\vert i-j\vert \geq 2$;}\label{rel-def-QHA3}\\[0.2em]
\tau_{i}x_{a}1_{\alpha}-x_{s_{i}(a)}\tau_{i}1_{\alpha}&=\left\{
\begin{array}{ll}
-1_{\alpha}&\text{if $a=i$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
1_{\alpha}&\text{if $a=i+1$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
0&\text{otherwise;}
\end{array}
\right.\label{rel-def-QHA4}\\[0.2em]
\tau_{i}^{2}1_{\alpha}&=Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1})1_{\alpha};\label{rel-def-QHA5}\\[0.2em]
\nonumber\tau_{i+1}\tau_{i}\tau_{i+1}1_{\alpha}-\tau_{i}\tau_{i+1}\tau_{i}1_{\alpha}&=\end{align}
\begin{align}
\left\{
\begin{array}{ll}
(x_{i+2}-x_{i})^{-1}(Q_{\alpha_i, \alpha_{i+1}}(x_{i+2}, x_{i+1})-Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1}))1_{\alpha}&\text{if $\alpha_i = \alpha_{i+2}$},\\[0.3em]
0&\text{otherwise,}
\end{array}
\right.\label{rel-def-QHA6}
\end{align}
for $\alpha,\alpha'\in K^{n},$ $1\leq a,b\leq n$ and $1\leq i,j\leq n-1,$ and where\\
\[Q_{\alpha_i, \alpha_{i+1}}(u, v)=\left\{
\begin{array}{ll}
0&\text{if $\alpha_i = \alpha_{i+1}$},\\[0.05em]
1&\text{if $\alpha_i\nslash \alpha_{i+1}$},\\[0.05em]
v-u&\text{if $\alpha_i\rightarrow \alpha_{i+1}$},\\[0.05em]
u-v&\text{if $\alpha_i\leftarrow \alpha_{i+1}$},\\[0.05em]
-(u-v)^{2}&\text{if $\alpha_i\rightleftarrows \alpha_{i+1}$}.
\end{array}
\right.\]
\end{definition}

By \eqref{rel-def-QHA4}, we get the following useful identity in $H_{n}(\Gamma)$:\vspace{0.15cm}
\begin{align}
f\tau_{i}1_{(\nu, j)}=\left\{
\begin{array}{ll}
\tau_{i}{}^{s_{i}}f1_{(\nu, j)}+\partial_{i}(f)1_{(\nu, j)}&\text{if $(\nu_i, j_i)=(\nu_{i+1}, j_{i+1})$},\\[0.2em]
\tau_{i}{}^{s_{i}}f1_{(\nu, j)}&\text{otherwise},
\end{array}
\right.\label{commu-relations}
\end{align}
\vspace{0.15cm}
for any $1\leq i\leq n-1,$ $(\nu, j)\in K^{n}$ and $f\in k[[x_1,\dots,x_n]]$, and where
\begin{equation*}
\partial_{i}(f):=\frac{f-{}^{s_{i}}f}{x_{i+1}-x_{i}}.
\end{equation*}


In the rest of this section, we always assume that $q\neq 1.$ For each $(\nu, j)\in K^{n}$ and $1\leq i\leq n-1,$ we define the following element:
\[Q_{i}(\nu, j)=
\begin{cases}
\begin{cases}
q(x_{i+1}+1)-(x_{i}+1) & \text{if } \nu_i = \nu_{i+1},
\\
\left(q^{-1}(x_{i}+1)-(x_{i+1}+1)\right)^{-1} & \text{if } \nu_{i+1} =q\nu_{i},
\\
\frac{\nu_{i+1}(x_{i+1}+1)-q\nu_{i}(x_{i}+1)}
{\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)}
 & \text{otherwise,}
\end{cases}
& \text{if } j_i = j_{i+1},
\\
f_{i, j} & \text{if } j_i \neq j_{i+1},
\end{cases}
\]
\setlength{\parskip}{2pt}where $f_{i,j}\in \{1, q\}$ is given by

\[f_{i, j}=
\begin{cases}
q & \text{if } j_i < j_{i+1},
\\[0.1em]
1& \text{if } j_i > j_{i+1},
\end{cases}
\]
and

\[P_{i}(\nu, j)=
\begin{cases}
\begin{cases}
1 & \text{if } \nu_i = \nu_{i+1},
\\
\frac{(q-1)\nu_{i+1}(x_{i+1}+1)}{\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)}
 & \text{otherwise,}
\end{cases}
& \text{if } j_i = j_{i+1},
\\
0 & \text{if } j_i \neq j_{i+1}.
\end{cases}
\]

The following lemma can be easily checked by definition.
\begin{lemma}
\begin{align} P_{i}(\nu, j)+{}^{s_{i}}P_{i}(s_{i}\cdot(\nu, j))&=1-q \quad\text{ if }\nu_i \neq \nu_{i+1} \text{ and } j_i = j_{i+1};\label{P-relations1}\\[0.2em]
{}^{s_{i}}P_{i+1}(s_{i}\cdot(\nu, j))&={}^{s_{i+1}}P_{i}(s_{i+1}\cdot(\nu, j))\quad\text{ for any }(\nu, j)\in K^{n}. \label{P-relations2}
\end{align}
\end{lemma}
The following lemma can also be easily checked by definition.
\begin{lemma}
\begin{align}
{}^{s_{i}}Q_{i+1}(s_{i+1}s_{i}\cdot(\nu, j))&={}^{s_{i+1}}Q_{i}(s_{i}s_{i+1}\cdot(\nu, j))\quad\text{ for any }(\nu, j)\in K^{n}. \label{Q-relations1}
\end{align}
\end{lemma}
We also need the following key lemma.

\begin{lemma}
\begin{align}
\hspace{-0.1cm}{}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)=\left\{
\begin{array}{ll}
\hspace{-0.15cm}(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))&\text{if $(\nu_i, j_{i})\nslash (\nu_{i+1}, j_{i+1})$},\\[0.3em]
\hspace{-0.15cm}\frac{(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))}{x_{i+1}-x_{i}}&\text{if $(\nu_i, j_{i})\rightarrow (\nu_{i+1}, j_{i+1})$},\\[0.3em]
\hspace{-0.15cm}\frac{(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))}{x_{i}-x_{i+1}}&\text{if $(\nu_i, j_{i})\leftarrow (\nu_{i+1}, j_{i+1})$},\\[0.3em]
\hspace{-0.15cm}\frac{(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))}{(x_{i}-x_{i+1})(x_{i+1}-x_{i})}&\text{if $(\nu_i, j_{i})\rightleftarrows (\nu_{i+1}, j_{i+1})$}.\label{Q-relations2}
\end{array}
\right.\end{align}
\end{lemma}

\begin{proof}
(1) If $j_{i}\neq j_{i+1}$, then $(\nu_i, j_{i})\nslash (\nu_{i+1}, j_{i+1})$, in this case \[{}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)=f_{i,j}f_{i, s_{i}(j)}=q,\] while $(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))=q.$\vspace{0.25cm}

(2) If $j_{i}= j_{i+1}$ and $(\nu_i, j_{i})\nslash (\nu_{i+1}, j_{i+1}),$ then we have
\begin{align*}
{}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)&=\frac{\nu_{i}(x_{i}+1)-q\nu_{i+1}(x_{i+1}+1)}
{\nu_{i+1}(x_{i+1}+1)-\nu_{i}(x_{i}+1)}\cdot\frac{\nu_{i+1}(x_{i+1}+1)-q\nu_{i}(x_{i}+1)}
{\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)}\\
&=\frac{\big(\nu_{i}(x_{i}+1)-q\nu_{i+1}(x_{i+1}+1)\big)\cdot\big(q\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)}{\big(\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)^{2}},
\end{align*}
while
\begin{align}
&(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))\notag\\=&q-\frac{(q-1)^{2}\nu_{i+1}(x_{i+1}+1)}{\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)}-
\frac{(q-1)^{2}\nu_{i+1}^{2}(x_{i+1}+1)^{2}}{\big(\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)^{2}}\notag\\
=&\big\{q\big(\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)^{2}-(q-1)^{2}\nu_{i+1}(x_{i+1}+1)\big(\nu_{i}(x_{i}+1)-
\nu_{i+1}(x_{i+1}+1)\big)\notag\\
&-(q-1)^{2}\nu_{i+1}^{2}(x_{i+1}+1)^{2}\big\}\cdot\big(\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)^{-2}\notag\\
=&\frac{q\nu_{i}^{2}(x_{i}+1)^{2}+q\nu_{i+1}^{2}(x_{i+1}+1)^{2}-(q^{2}+1)\nu_{i}\nu_{i+1}(x_{i}+1)(x_{i+1}+1)}
{\big(\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)^{2}}\notag\\
=&\frac{\big(\nu_{i}(x_{i}+1)-q\nu_{i+1}(x_{i+1}+1)\big)\cdot\big(q\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)}
{\big(\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)\big)^{2}}.\label{Q-relations3}
\end{align}\vspace{0.25cm}

(3) If $j_{i}= j_{i+1}$ and $(\nu_i, j_{i})\rightarrow (\nu_{i+1}, j_{i+1}),$ then $\nu_{i+1}=q\nu_{i},$ and we have
\begin{align*}
{}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)&=\frac{\nu_{i}(x_{i}+1)-q\nu_{i+1}(x_{i+1}+1)}
{\nu_{i+1}(x_{i+1}+1)-\nu_{i}(x_{i}+1)}\cdot\frac{1}{q^{-1}(x_{i}+1)-(x_{i+1}+1)}\\
&=\frac{q(x_{i+1}+1)-q^{-1}(x_{i}+1)}{\big(q^{-1}(x_{i}+1)-(x_{i+1}+1)\big)^{2}},
\end{align*}
by setting $\nu_{i+1}=q\nu_{i}$ in \eqref{Q-relations3}, we get
\begin{align*}
(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))&=\frac{\big(\nu_{i}(x_{i}+1)-q^{2}\nu_{i}(x_{i+1}+1)\big)\cdot\big(q\nu_{i}(x_{i}+1)-q\nu_{i}(x_{i+1}+1)\big)}
{\big(\nu_{i}(x_{i}+1)-q\nu_{i}(x_{i+1}+1)\big)^{2}}\\
&=\frac{\big(q(x_{i+1}+1)-q^{-1}(x_{i}+1)\big)\cdot(x_{i+1}-x_{i})}{\big(q^{-1}(x_{i}+1)-(x_{i+1}+1)\big)^{2}}.
\end{align*}\vspace{0.25cm}

(4) If $j_{i}= j_{i+1}$ and $(\nu_i, j_{i})\leftarrow (\nu_{i+1}, j_{i+1}),$ then $\nu_{i}=q\nu_{i+1},$ and we have
\begin{align*}
{}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)&=\frac{1}{q^{-1}(x_{i+1}+1)-(x_{i}+1)}\cdot
\frac{\nu_{i+1}(x_{i+1}+1)-q\nu_{i}(x_{i}+1)}{\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)}\\
&=\frac{q(x_{i}+1)-q^{-1}(x_{i+1}+1)}{\big(q^{-1}(x_{i+1}+1)-(x_{i}+1)\big)^{2}},
\end{align*}
by setting $\nu_{i}=q\nu_{i+1}$ in \eqref{Q-relations3}, we get
\begin{align*}
(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))&=\frac{\big(\nu_{i}(x_{i}+1)-\nu_{i}(x_{i+1}+1)\big)\cdot\big(q\nu_{i}(x_{i}+1)-q^{-1}\nu_{i}(x_{i+1}+1)\big)}
{\big(\nu_{i}(x_{i}+1)-q^{-1}\nu_{i}(x_{i+1}+1)\big)^{2}}\\
&=\frac{\big(q(x_{i}+1)-q^{-1}(x_{i+1}+1)\big)\cdot(x_{i}-x_{i+1})}{\big(q^{-1}(x_{i+1}+1)-(x_{i}+1)\big)^{2}}.
\end{align*}\vspace{0.25cm}

