\frac{1}{-(x_{i}+1)-(x_{i+1}+1)}\\
&=\frac{1}{(x_{i}+x_{i+1}+2)^{2}},
\end{align*}
by setting $\nu_{i+1}=-\nu_{i}$ in \eqref{Q-relations3}, we get
\begin{align*}
